<template><scroll-view scroll-y class="contract-sheet ui-v2" :class="{'ui-large-text':large}"><text class="contract-title">组件尺寸验收 · 仅开发</text><AppButton variant="text" @click="$emit('close')">关闭，不保存任何资料</AppButton><AppSurface variant="primary"><text class="contract-title">把今天，留在这里。</text><view class="contract-actions"><AppButton variant="primary" icon="compose">记录今天</AppButton><AppButton icon="chatbubble">AI 问诊</AppButton></view></AppSurface><AppSegmented v-model="tab" :options="[{value:'health',label:'健康与观察'},{value:'life',label:'日常与照片'}]"/><view class="event-grid"><view v-for="(label,i) in events" :key="label" class="event-chip" :class="{'event-chip-active':selected.includes(i)}" @click="selected=selected.includes(i)?selected.filter(v=>v!==i):[...selected,i]"><text class="choice-face">{{label}}</text></view></view><view class="contract-actions"><AppButton variant="primary" disabled>禁用状态</AppButton><AppButton variant="primary" loading>保存中</AppButton></view><AppButton variant="primary">保存日常记录</AppButton><AppSurface><AppSettingsRow title="账号与安全" description="登录设备与账号设置" action/><AppSettingsRow title="宠物档案与展示设置" action/></AppSurface><AppButton variant="text" @click="large=!large">{{large?'恢复普通字号几何':'检查大字布局'}}</AppButton></scroll-view></template>
<script>export default{emits:['close'],data(){return{tab:'health',large:false,selected:[],events:['饮食','饮水','精神','便便','体重','睡眠','外出 / 运动','洗澡 / 清洁','疫苗 / 驱虫','用药','异常情况','小事 / 备注']}}};</script>
<style scoped>.contract-sheet{position:fixed;inset:0;z-index:150;height:100vh;padding:calc(var(--status-bar-height,0px) + 20px) 20px 30px;background:var(--ui-page);box-sizing:border-box}.contract-title{display:block;font-size:21px;line-height:30px;margin-bottom:16px}.contract-actions{display:flex;gap:10px;margin:16px 0}.contract-actions :deep(.ui-button){flex:1;min-width:0}.contract-sheet :deep(.ui-segments){margin-top:20px}.contract-sheet :deep(.ui-surface){margin-top:16px}</style>
